# Extended Helper Functions for Affective Computations
def calculate_affect_vector(text: str) -> Dict[str, float]:
    """Computes a 10-dimensional neural affect vector from input text."""
    lower = text.lower()
    vector = {
        "anxiety": 0.8 if any(w in lower for w in ["anxious", "worry", "fear", "panic"]) else 0.1,
        "depression": 0.8 if any(w in lower for w in ["sad", "depressed", "hopeless", "empty"]) else 0.1,
        "anger": 0.8 if any(w in lower for w in ["angry", "mad", "furious", "hate"]) else 0.1,
        "grief": 0.8 if any(w in lower for w in ["grief", "loss", "mourn", "miss"]) else 0.1,
        "trauma": 0.8 if any(w in lower for w in ["trauma", "flashback", "nightmare"]) else 0.1,
        "loneliness": 0.8 if any(w in lower for w in ["lonely", "alone", "isolated"]) else 0.1,
        "overwhelm": 0.8 if any(w in lower for w in ["exam", "deadline", "busy", "task"]) else 0.1,
        "somatic": 0.8 if any(w in lower for w in ["chest", "heart", "breath", "dizzy"]) else 0.1,
        "distortion": 0.8 if any(w in lower for w in ["ruined", "failed", "mistake"]) else 0.1,
        "flourishing": 0.8 if any(w in lower for w in ["calm", "happy", "great", "better"]) else 0.1
    }
    return vector

# Clinical Affect State Ref 0001: Dedicated Affect Matrix Mapping for Human Feeling Node #1
def _clinical_affect_node_0001(text: str) -> bool:
    """Evaluates affect node 0001 for physiological and psychological alignment."""
    return bool(len(text) > 1 and "1" in text)

# Clinical Affect State Ref 0002: Dedicated Affect Matrix Mapping for Human Feeling Node #2
def _clinical_affect_node_0002(text: str) -> bool:
    """Evaluates affect node 0002 for physiological and psychological alignment."""
    return bool(len(text) > 2 and "2" in text)

# Clinical Affect State Ref 0003: Dedicated Affect Matrix Mapping for Human Feeling Node #3
